// BenchmarkFifoSuite measures each callable of the suite of Fifo on
// fifoIdle.
func BenchmarkFifoSuite(b *testing.B) {
	b.Run("Push", func(b *testing.B) {
		referencetest.BenchFifoSuite(b, referencetest.FifoChecks.Push.Callable, fifoIdle)
	})
	b.Run("Pop", func(b *testing.B) {
		referencetest.BenchFifoSuite(b, referencetest.FifoChecks.Pop.Callable, fifoIdle)
	})
	b.Run("Len", func(b *testing.B) {
		referencetest.BenchFifoSuite(b, referencetest.FifoChecks.Len.Callable, fifoIdle)
	})
}

